import os, time, threading, ctypes
from ctypes import c_uint32, c_uint64

# A compact but unrolled-enough ChaCha20 in pure python using ctypes buffers, 
# processing 1 block, to see python overhead. If one block is ~50us, 40MB is hopeless.
# We'll try a numba-less approach: write C and compile with cc -O3 -march=native, load via ctypes.
# That's the real test of whether a better implementation exists.

src = r'''
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <immintrin.h>

static inline uint32_t rotl(uint32_t x, int n){ return (x<<n)|(x>>(32-n)); }

/* 4-block AVX2-ish using scalar first as baseline, then a real AVX2 8-block if time */

void chacha20_xor_scalar(uint8_t *out, const uint8_t *in, size_t len,
                         const uint8_t key[32], const uint8_t nonce[12], uint32_t counter){
    uint32_t k[8];
    memcpy(k, key, 32);
    uint32_t n0,n1,n2;
    memcpy(&n0, nonce, 4); memcpy(&n1, nonce+4, 4); memcpy(&n2, nonce+8, 4);
    const uint32_t c0=0x61707865, c1=0x3320646e, c2=0x79622d32, c3=0x6b206574;
    while(len){
        uint32_t x0=c0,x1=c1,x2=c2,x3=c3;
        uint32_t x4=k[0],x5=k[1],x6=k[2],x7=k[3];
        uint32_t x8=k[4],x9=k[5],x10=k[6],x11=k[7];
        uint32_t x12=counter, x13=n0, x14=n1, x15=n2;
        for(int i=0;i<10;i++){
            #define QR(a,b,c,d) a+=b; d^=a; d=rotl(d,16); c+=d; b^=c; b=rotl(b,12); a+=b; d^=a; d=rotl(d,8); c+=d; b^=c; b=rotl(b,7);
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
            #undef QR
        }
        x0+=c0; x1+=c1; x2+=c2; x3+=c3;
        x4+=k[0]; x5+=k[1]; x6+=k[2]; x7+=k[3];
        x8+=k[4]; x9+=k[5]; x10+=k[6]; x11+=k[7];
        x12+=counter; x13+=n0; x14+=n1; x15+=n2;
        uint32_t s[16]={x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15};
        size_t m = len<64?len:64;
        for(size_t i=0;i<m;i++) out[i] = in[i] ^ ((uint8_t*)s)[i];
        out+=m; in+=m; len-=m; counter++;
    }
}

/* AVX2 4-way (processes 256 bytes). Portable enough. */
void chacha20_xor_avx2(uint8_t *out, const uint8_t *in, size_t len,
                       const uint8_t key[32], const uint8_t nonce[12], uint32_t counter){
    /* fall back for tail via scalar after main */
    uint32_t k[8]; memcpy(k, key, 32);
    uint32_t n0,n1,n2; memcpy(&n0,nonce,4); memcpy(&n1,nonce+4,4); memcpy(&n2,nonce+8,4);
    const __m256i c0 = _mm256_set1_epi32(0x61707865);
    const __m256i c1 = _mm256_set1_epi32(0x3320646e);
    const __m256i c2 = _mm256_set1_epi32(0x79622d32);
    const __m256i c3 = _mm256_set1_epi32(0x6b206574);
    const __m256i k0 = _mm256_set1_epi32(k[0]);
    const __m256i k1 = _mm256_set1_epi32(k[1]);
    const __m256i k2 = _mm256_set1_epi32(k[2]);
    const __m256i k3 = _mm256_set1_epi32(k[3]);
    const __m256i k4 = _mm256_set1_epi32(k[4]);
    const __m256i k5 = _mm256_set1_epi32(k[5]);
    const __m256i k6 = _mm256_set1_epi32(k[6]);
    const __m256i k7 = _mm256_set1_epi32(k[7]);
    const __m256i nn0 = _mm256_set1_epi32(n0);
    const __m256i nn1 = _mm256_set1_epi32(n1);
    const __m256i nn2 = _mm256_set1_epi32(n2);
    const __m256i rot16 = _mm256_set_epi8(13,12,15,14,9,8,11,10,5,4,7,6,1,0,3,2,13,12,15,14,9,8,11,10,5,4,7,6,1,0,3,2);
    const __m256i rot8  = _mm256_set_epi8(14,13,12,15,10,9,8,11,6,5,4,7,2,1,0,3,14,13,12,15,10,9,8,11,6,5,4,7,2,1,0,3);

    while(len >= 256){
        __m256i ctr = _mm256_set_epi32(0,0,0,counter+7, 0,0,0,counter+6); /* wrong layout, fix below */
        /* each lane is a 128-bit block; we want counter+0..+7 in the low dword of each 128-bit lane.
           ymm lane layout for set_epi32 is [7,6,5,4,3,2,1,0] where 0 is lowest. 
           128-bit lane0 = dwords 0..3, lane1 = dwords 4..7.
           We need 8 independent counters, one per block, but AVX2 256-bit has only 2x128 lanes.
           So this processes 2 blocks per ymm register if we do vertical? 
           Better: 8 ymm registers holding the same state word across 8 blocks.
           counter vector: blocks 0..7 */
        __m256i x0=c0,x1=c1,x2=c2,x3=c3;
        __m256i x4=k0,x5=k1,x6=k2,x7=k3;
        __m256i x8=k4,x9=k5,x10=k6,x11=k7;
        __m256i x12=_mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,counter+3,counter+2,counter+1,counter);
        __m256i x13=nn0, x14=nn1, x15=nn2;

        #define QR(a,b,c,d) \
            a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=_mm256_shuffle_epi8(d, rot16); \
            c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=_mm256_or_si256(_mm256_slli_epi32(b,12), _mm256_srli_epi32(b,20)); \
            a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=_mm256_shuffle_epi8(d, rot8); \
            c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=_mm256_or_si256(_mm256_slli_epi32(b,7), _mm256_srli_epi32(b,25));
        for(int i=0;i<10;i++){
            QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
            QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
        }
        #undef QR
        x0=_mm256_add_epi32(x0,c0); x1=_mm256_add_epi32(x1,c1); x2=_mm256_add_epi32(x2,c2); x3=_mm256_add_epi32(x3,c3);
        x4=_mm256_add_epi32(x4,k0); x5=_mm256_add_epi32(x5,k1); x6=_mm256_add_epi32(x6,k2); x7=_mm256_add_epi32(x7,k3);
        x8=_mm256_add_epi32(x8,k4); x9=_mm256_add_epi32(x9,k5); x10=_mm256_add_epi32(x10,k6); x11=_mm256_add_epi32(x11,k7);
        x12=_mm256_add_epi32(x12,_mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,counter+3,counter+2,counter+1,counter));
        x13=_mm256_add_epi32(x13,nn0); x14=_mm256_add_epi32(x14,nn1); x15=_mm256_add_epi32(x15,nn2);

        /* transpose 8 blocks of 16 dwords into sequential output. 
           Store each dword-lane. Simple approach: extract 32-bit lanes. */
        uint32_t b0[8],b1[8],b2[8],b3[8],b4[8],b5[8],b6[8],b7[8];
        uint32_t b8[8],b9[8],b10[8],b11[8],b12[8],b13[8],b14[8],b15[8];
        _mm256_storeu_si256((__m256i*)b0, x0);
        _mm256_storeu_si256((__m256i*)b1, x1);
        _mm256_storeu_si256((__m256i*)b2, x2);
        _mm256_storeu_si256((__m256i*)b3, x3);
        _mm256_storeu_si256((__m256i*)b4, x4);
        _mm256_storeu_si256((__m256i*)b5, x5);
        _mm256_storeu_si256((__m256i*)b6, x6);
        _mm256_storeu_si256((__m256i*)b7, x7);
        _mm256_storeu_si256((__m256i*)b8, x8);
        _mm256_storeu_si256((__m256i*)b9, x9);
        _mm256_storeu_si256((__m256i*)b10, x10);
        _mm256_storeu_si256((__m256i*)b11, x11);
        _mm256_storeu_si256((__m256i*)b12, x12);
        _mm256_storeu_si256((__m256i*)b13, x13);
        _mm256_storeu_si256((__m256i*)b14, x14);
        _mm256_storeu_si256((__m256i*)b15, x15);
        uint32_t *rows[16]={b0,b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15};
        for(int blk=0; blk<8; blk++){
            uint32_t s[16];
            for(int r=0;r<16;r++) s[r]=rows[r][blk];
            const uint8_t *ip = in + blk*64;
            uint8_t *op = out + blk*64;
            const uint8_t *sp = (const uint8_t*)s;
            for(int j=0;j<64;j++) op[j]=ip[j]^sp[j];
        }
        in += 256; out += 256; len -= 256; counter += 8;
    }
    if(len) chacha20_xor_scalar(out, in, len, key, nonce, counter);
}
'''
